#ifndef CNN_TOP_H
#define CNN_TOP_H

// -------------------------------------------------------------------------
// cnn_top.h -- AXI-Stream CNN accelerator for Vitis HLS
//
// Architecture : 5-layer GTSRB CNN backbone (PL side)
//                FC head runs on the PS (ARM) side
// Fixed-point  : Q6.10  (data_t = ap_fixed<16,6>)
// Accumulator  : Q16.16 (accum_t = ap_fixed<32,16>) -- prevents overflow
// Weights      : Static on-chip ROM from cnn_weights_data.h
//                (generated by generate_weights.py from best_model.pth)
//
// Stream IN  : 3*32*32 = 3072 int16 words (one Q6.10 pixel per 32-bit word)
// Stream OUT : 128*4*4 = 2048 int16 words (pool3 feature map, Q6.10)
//              TLAST asserted on final output word.
//
// Interface: AXI-Stream + AXI-Lite control (ap_ctrl_hs)
// -------------------------------------------------------------------------

#include "ap_fixed.h"
#include "hls_stream.h"
#include "ap_axi_sdata.h"

typedef ap_fixed<16, 6, AP_RND_ZERO, AP_SAT>   data_t;   // Q6.10 -- data & weights
typedef ap_fixed<32, 16, AP_RND_ZERO, AP_SAT>  accum_t;  // Q16.16 -- accumulator
typedef ap_axiu<32, 1, 1, 1>                    axis_t;   // 32-bit AXI-Stream word

void cnn_top(
    hls::stream<axis_t>& s_axis_input,
    hls::stream<axis_t>& m_axis_output
);

#endif // CNN_TOP_H
